const WIDTH = 115.55;

// Colors go through `style` (not presentation attributes) so they can be
// CSS variables — the header cross-fades the lockup via --logo-* vars.
function Glyph({ stroke }: { stroke: string }) {
  return (
    <path
      d={GLYPH}
      fill="none"
      style={{ stroke }}
      strokeWidth="2.6"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="transition-[stroke] duration-300"
    />
  );
}

/** The mark: a "V" whose right stroke lifts off as an arrow — money in motion. */
export function LogoMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 32 32"
      className={cn("size-8", className)}
      aria-hidden="true"
    >
      <rect width="32" height="32" rx="9" fill="currentColor" />
      <Glyph stroke="var(--logo-stroke, #fff)" />
    </svg>
  );
}

/**
 * Full lockup. `light` is for photos and violet surfaces. Ships inside the
 * header island, so it avoids `cn` (tailwind-merge) to keep the bundle lean.
 */
export function Logo({
  className,
  tone = "ink",
}: {
  className?: string;
  tone?: "ink" | "light";
}) {
  const light = tone === "light";
  return (
    <svg
      viewBox={`0 0 ${WIDTH} 32`}
      width={Math.round((WIDTH * 28) / 32)}
      height={28}
      role="img"
      aria-label="VRS Pay"
      className={
        className ? `block h-7 w-auto ${className}` : "block h-7 w-auto"
      }
    >
      <rect
        width="32"
        height="32"
        rx="9"
        style={{ fill: `var(--logo-tile, ${light ? "#fff" : "#6936f5"})` }}
        className="transition-[fill] duration-300"
      />
      <Glyph stroke={`var(--logo-glyph, ${light ? "#6936f5" : "#fff"})`} />
      <path
        d={WORDMARK}
        style={{ fill: `var(--logo-text, ${light ? "#fff" : "#0b0b12"})` }}
        className="transition-[fill] duration-300"
      />
    </svg>
  );
}
